// Behaviour for the portfolio page, ported from the Design Component script in
// source/Main.dc.html: accordion case studies with prev/next, the Fonepay image
// lightbox, the typing "hats" in the hero, the dark theme for #work on scroll,
// and click-to-play on the video posters.
(function () {
  'use strict';

  // Case order and lightbox images come from the page itself (generated by Jekyll
  // from _data/cases.yml), so nothing here needs editing when cases change.
  var CASE_ORDER = Array.prototype.map.call(document.querySelectorAll('.case-item'), function (el) {
    return el.id.replace(/^case-/, '');
  });

  // Per-case image sets for the lightbox (prev/next steps through this list).
  var CASE_GALLERIES = {};
  document.querySelectorAll('.case-item[data-gallery]').forEach(function (el) {
    try {
      CASE_GALLERIES[el.id.replace(/^case-/, '')] = JSON.parse(el.getAttribute('data-gallery')).map(function (g) {
        return { src: g.image, alt: g.alt || '', caption: g.caption || '' };
      });
    } catch (err) { /* malformed data: that case simply has no lightbox */ }
  });

  var HATS = [
    ['Brand & Creative Strategist', 'specialising in campaign planning, creative execution and integrated channel tactics.'],
    ['B2B Marketing Specialist', 'helping businesses showcase their impact with human led stories and powerful brand partnerships.'],
    ['Branded Content Manager', 'obsessed with finding the right screen and format to grip audiences.'],
    ['Content Planner', 'fine-tuning messaging points and content to match consumer need states.'],
    ['Third Culture Adult', 'adaptable to different clients and adept at building cross-cultural connections.'],
    ['Hip-hop fanatic', 'with a passion for narratives that flow to a beat with rhyme and reason.']
  ];

  // ------------------------------------------------------------------ videos
  // Clicking the play overlay (the wrapper's ::before) starts the clip; the
  // overlay hides while the video plays.
  function markVideo(e, on) {
    var t = e.target;
    if (t && t.tagName === 'VIDEO' && t.parentElement) t.parentElement.classList.toggle('is-playing', on);
  }
  document.addEventListener('click', function (e) {
    var w = e.target;
    if (w && w.classList && w.classList.contains('modal-video-wrap') && !w.classList.contains('is-playing')) {
      var v = w.querySelector('video');
      if (v && typeof v.play === 'function') { var r = v.play(); if (r && r.catch) r.catch(function () {}); }
    }
  });
  document.addEventListener('play', function (e) { markVideo(e, true); }, true);
  document.addEventListener('playing', function (e) { markVideo(e, true); }, true);
  document.addEventListener('pause', function (e) { markVideo(e, false); }, true);
  document.addEventListener('ended', function (e) { markVideo(e, false); }, true);

  // ------------------------------------------------------------- hero hats
  (function () {
    var reduce = typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var hat = 0;
    var n = 0;
    function paint(solid) {
      var bEl = document.getElementById('hat-title');
      var tEl = document.getElementById('hat-title-text');
      var dEl = document.getElementById('hat-desc');
      if (!bEl || !tEl || !dEl) return;
      bEl.querySelectorAll('.hat-caret').forEach(function (c) { c.remove(); });
      dEl.querySelectorAll('.hat-caret').forEach(function (c) { c.remove(); });
      var t = HATS[hat][0];
      var d = HATS[hat][1];
      tEl.textContent = t.slice(0, Math.min(n, t.length));
      dEl.textContent = n > t.length ? d.slice(0, n - t.length) : '';
      var caret = document.createElement('span');
      caret.className = 'hat-caret' + (solid ? ' solid' : '');
      (n > t.length ? dEl : bEl).appendChild(caret);
    }
    function step(phase) {
      var total = HATS[hat][0].length + HATS[hat][1].length;
      var tl = HATS[hat][0].length;
      if (phase === 'type') {
        n = n + 1;
        paint(true);
        if (n >= total) { paint(false); setTimeout(function () { step('erase'); }, 3200); return; }
        setTimeout(function () { step('type'); }, n <= tl ? 55 : 22);
      } else {
        n = n - 1;
        paint(true);
        if (n <= 0) {
          n = 0;
          hat = (hat + 1) % HATS.length;
          paint(false);
          setTimeout(function () { step('type'); }, 600);
          return;
        }
        setTimeout(function () { step('erase'); }, 12);
      }
    }
    if (!reduce) {
      setTimeout(function () {
        n = HATS[0][0].length + HATS[0][1].length;
        paint(false);
        setTimeout(function () { step('erase'); }, 2500);
      }, 800);
    }
  })();

  // ------------------------------------------------- dark #work on scroll
  var work = document.getElementById('work');
  function checkWork() {
    if (!work) return;
    var r = work.getBoundingClientRect();
    var vh = window.innerHeight || 800;
    var on = r.top < vh * 0.45 && r.bottom > vh * 0.35;
    work.classList.toggle('work-dark', on);
  }
  window.addEventListener('scroll', checkWork, { passive: true });
  window.addEventListener('resize', checkWork);
  setTimeout(checkWork, 0);

  // ------------------------------------------------------- case studies
  var activeCase = null;

  function resetVideos(el) {
    el.querySelectorAll('video').forEach(function (v) {
      if (!v.paused || v.currentTime > 0) { v.pause(); v.load(); }
    });
  }

  function setActive(id) {
    activeCase = id;
    CASE_ORDER.forEach(function (cid) {
      var el = document.getElementById('case-' + cid);
      if (!el) return;
      var open = cid === id;
      var btn = el.querySelector('.case-toggle');
      var detail = el.querySelector('.case-detail');
      el.classList.toggle('is-lit', open);
      btn.classList.toggle('is-open', open);
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (!open && !detail.hidden) resetVideos(detail);
      detail.hidden = !open;
    });
  }

  function scrollToCase(id) {
    requestAnimationFrame(function () {
      var el = document.getElementById('case-' + id);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  }

  document.addEventListener('click', function (e) {
    var toggleBtn = e.target.closest('.case-toggle');
    if (toggleBtn) {
      var id = toggleBtn.closest('.case-item').id.replace('case-', '');
      var isOpen = activeCase === id;
      setActive(isOpen ? null : id);
      if (!isOpen) scrollToCase(id);
      return;
    }
    var navBtn = e.target.closest('.case-nav-btn');
    if (navBtn && activeCase) {
      var idx = CASE_ORDER.indexOf(activeCase);
      var delta = navBtn.classList.contains('prev') ? -1 : 1;
      var target = CASE_ORDER[(idx + delta + CASE_ORDER.length) % CASE_ORDER.length];
      setActive(target);
      scrollToCase(target);
    }
  });

  // ------------------------------------------------------------ lightbox
  var lb = document.getElementById('lightbox');
  var lbImg = document.getElementById('lightbox-img');
  var lbCap = document.getElementById('lightbox-caption');
  var lbCase = null;
  var lbIndex = 0;

  function renderLightbox() {
    var imgs = lbCase ? (CASE_GALLERIES[lbCase] || []) : [];
    var cur = imgs[lbIndex];
    if (!cur) {
      lb.hidden = true;
      lbImg.removeAttribute('src');
      lbCap.textContent = '';
      return;
    }
    lbImg.src = cur.src;
    lbImg.alt = cur.alt;
    lbCap.textContent = cur.caption;
    lb.hidden = false;
  }

  document.addEventListener('click', function (e) {
    var fig = e.target.closest('[data-lb-index]');
    if (!fig) return;
    lbCase = fig.closest('.case-item').id.replace(/^case-/, '');
    lbIndex = parseInt(fig.getAttribute('data-lb-index'), 10) || 0;
    renderLightbox();
  });

  lb.addEventListener('click', function (e) {
    if (e.target === lbImg) return;
    var btn = e.target.closest('[data-lb]');
    var action = btn ? btn.getAttribute('data-lb') : 'close';
    if (action === 'close') {
      lbCase = null;
    } else {
      var imgs = CASE_GALLERIES[lbCase] || [];
      if (!imgs.length) return;
      lbIndex = (lbIndex + (action === 'prev' ? -1 : 1) + imgs.length) % imgs.length;
    }
    renderLightbox();
  });
})();
